<script lang="ts">
  import InvoicePaymentsPanel from '$lib/components/business/invoice-payments-panel.svelte';
  import InvoiceDirectoryPicker from '$lib/components/business/invoice-directory-picker.svelte';
  import InvoiceTaxPicker from '$lib/components/business/invoice-tax-picker.svelte';
  import { formatDate, formatDateTime } from '$lib/dates';
  import AmountInput from '$lib/components/forms/amount-input.svelte';
  import LoadingScope from '$lib/components/shared/loading-scope.svelte';
  import DatePicker from '$lib/components/forms/date-picker.svelte';
  import ChoiceSelect from '$lib/components/forms/choice-select.svelte';
  import {getContext as privacyContext} from 'svelte';
  import {concealed,PRIVACY_CONTEXT,type PrivacyState} from '$lib/privacy';
  const privacy=privacyContext<PrivacyState>(PRIVACY_CONTEXT);
 import {getContext} from 'svelte';import {page} from '$app/state';import {AUTH_UI_CONTEXT,type AuthUiState} from '$lib/i18n/auth';import {businessText} from '$lib/i18n/business';import {uxText} from '$lib/i18n/ux';import {Button} from '$lib/components/ui/button';import * as Card from '$lib/components/ui/card';import * as Field from '$lib/components/ui/field';import {Input} from '$lib/components/ui/input';import * as Dialog from '$lib/components/ui/dialog';import PageHeader from '$lib/components/shared/page-header.svelte';import MoneyDisplay from '$lib/components/shared/money-display.svelte';import ErrorState from '$lib/components/shared/error-state.svelte';import LoadingSkeleton from '$lib/components/shared/loading-skeleton.svelte';import InvoiceStatus from '$lib/components/business/invoice-status.svelte';
 type Workspace={selectedId:string;ready:boolean;items:{id:string;kind:string;timezone?:string;role?:string}[]};type Line={description:string;quantity:string;unitPrice:string;discountAmount:string;taxRate:string;taxRateId:string|null;netAmount?:string;taxAmount?:string;totalAmount?:string};
 const workspace=getContext<Workspace>('capybudget-workspaces'),ui=getContext<AuthUiState>(AUTH_UI_CONTEXT),t=(key:Parameters<typeof businessText>[1])=>businessText(ui.locale,key);
 let resendKey=$state(crypto.randomUUID());
 let taxRates:any[]=$state([]),taxEnabled=$state(false),taxRequest=0;
 async function loadTax(ws:string){const current=++taxRequest;taxRates=[];taxEnabled=false;try{const response=await fetch('/api/workspaces/'+ws+'/business-tax'),data=await response.json();if(current!==taxRequest||ws!==workspace.selectedId)return;if(!response.ok)throw new Error(data.message??t('error'));taxRates=data.rates;taxEnabled=data.settings.enabled;}catch(e){if(current===taxRequest)error=e instanceof Error?e.message:t('error');}}
 $effect(()=>{void (workspace as {revision?:number}).revision;if(workspace.ready&&workspace.selectedId)void loadTax(workspace.selectedId);});
 const ux=(key:Parameters<typeof uxText>[1])=>uxText(ui.locale,key);
 let reasonDialog=$state<{mode:'void'|'reverse';payment?:any}|null>(null),reasonText=$state('');
 let invoice:any=$state(null),accounts:any[]=$state([]),categories:any[]=$state([]),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),amount=$state(''),paidOn=$state(''),accountId=$state(''),forecastAccountId=$state(''),forecastDate=$state(''),categoryId=$state(''),reference=$state(''),requestId=0;
 const id=$derived(page.params.invoiceId);
 const role=$derived(workspace.items.find(w=>w.id===workspace.selectedId)?.role??'owner'),canEdit=$derived(role!=='viewer'),canManage=$derived(['owner','accountant'].includes(role));
 function dateToday(){const timezone=workspace.items.find(x=>x.id===workspace.selectedId)?.timezone??'Asia/Jakarta',parts=new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),get=(n:string)=>parts.find(p=>p.type===n)?.value;return get('year')+'-'+get('month')+'-'+get('day');}
 async function load(){if(!workspace.ready||!workspace.selectedId||!id)return;const current=++requestId;loading=true;error='';try{const [inv,ac,cat]=await Promise.all([fetch('/api/workspaces/'+workspace.selectedId+'/invoices/'+id),canManage?fetch('/api/workspaces/'+workspace.selectedId+'/accounts'):Promise.resolve(Response.json({items:[]})),canManage?fetch('/api/workspaces/'+workspace.selectedId+'/categories'):Promise.resolve(Response.json({items:[]}))]);const [idata,adata,cdata]=await Promise.all([inv.json(),ac.json(),cat.json()]);if(!inv.ok)throw new Error(idata.message??t('error'));if(current!==requestId)return;invoice=idata.invoice;accounts=adata.items??[];forecastAccountId=idata.invoice.expectedAccountId??'';forecastDate=idata.invoice.expectedPaymentOn??idata.invoice.dueDate;categories=(cdata.items??[]).filter((x:any)=>x.type==='income');paidOn=dateToday();accountId=accounts.find((x:any)=>x.currency===invoice.currency)?.id??'';categoryId=categories[0]?.id??'';}catch(e){if(current===requestId)error=e instanceof Error?e.message:t('error');}finally{if(current===requestId)loading=false;}}
 $effect(()=>{void (workspace as {revision?:number}).revision;if(workspace.ready&&workspace.selectedId&&id)void load();});
 async function call(url:string,method='POST',body?:unknown){const response=await fetch(url,{method,headers:body===undefined?undefined:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}),data=response.status===204?null:await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.message??t('error'));return data;}
 async function saveDraft(){if(busy)return;busy=true;error='';notice='';try{const body={version:invoice.version,contactId:invoice.contact_id,recipient:invoice.recipientSnapshot,issueDate:invoice.issue_date,dueDate:invoice.due_date,notes:invoice.notes,paymentInstructions:invoice.payment_instructions,lines:invoice.lines};const data=await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id,'PATCH',body);invoice=data.invoice;notice=t('saved');}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 function copyItem(item:any){if(invoice.lines.length>=100)return;invoice.lines=[...invoice.lines,{catalogItemId:item.id,catalogVersion:item.version,description:item.description||item.name,quantity:'1',unitPrice:String(item.unit_price),discountAmount:'0',taxRate:'0',taxRateId:item.tax_rate_id??''}];}
 function addLine(){invoice.lines=[...invoice.lines,{description:'',quantity:'1',unitPrice:'',discountAmount:'0',taxRate:'0',taxRateId:''}];}
 function removeLine(index:number){if(invoice.lines.length>1)invoice.lines=invoice.lines.filter((_:Line,i:number)=>i!==index);}
 async function issueInvoice(){if(busy)return;busy=true;error='';try{const data=await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/issue','POST',{version:invoice.version});invoice=data.invoice;}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 async function saveCollectionForecast(){if(busy||invoice.state!=='issued')return;busy=true;error='';try{const data=await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/collection-forecast','PATCH',{version:invoice.version,expectedPaymentOn:forecastDate||null,expectedAccountId:forecastAccountId||null});invoice={...invoice,...data};notice=ui.locale==='id'?'Asumsi penerimaan tersimpan.':'Collection estimate saved.';}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 async function sendInvoice(){if(busy)return;busy=true;error='';try{await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/send','POST',{version:invoice.version});notice=t('sending');await load();}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 async function resendPaymentLink(){
  if(busy||!invoice?.paymentLinkAvailable)return;
  const ws=workspace.selectedId,invoiceId=id;busy=true;error='';notice='';
  try{await call('/api/workspaces/'+ws+'/invoices/'+invoiceId+'/resend-payment-link','POST',{idempotencyKey:resendKey});resendKey=crypto.randomUUID();if(ws===workspace.selectedId&&invoiceId===id){notice=ui.locale==='id'?'Email tautan pembayaran masuk antrean untuk '+invoice.recipientSnapshot.email+'.':'Payment-link email queued for '+invoice.recipientSnapshot.email+'.';await load();}}
  catch(e){if(ws===workspace.selectedId&&invoiceId===id)error=e instanceof Error?e.message:t('error');}finally{busy=false;}
 }
 $effect(()=>{void workspace.selectedId;void id;resendKey=crypto.randomUUID();});
 async function downloadPdf(){if(busy)return;busy=true;error='';try{const response=await fetch('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/pdf',{method:'POST'});if(!response.ok){const data=await response.json();throw new Error(data.message??t('error'));}const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download=(invoice.number??'invoice-draft')+'.pdf';anchor.click();URL.revokeObjectURL(url);}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 function askVoid(){reasonText='';reasonDialog={mode:'void'};}
 function askReverse(payment:any){reasonText='';reasonDialog={mode:'reverse',payment};}
 async function confirmReason(){const dialog=reasonDialog,reason=reasonText.trim();if(!dialog||!reason||busy)return;busy=true;error='';try{if(dialog.mode==='void'){const data=await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/void','POST',{reason,effectiveOn:dateToday(),version:invoice.version});invoice=data.invoice;}else{await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/payments/'+dialog.payment.id+'/reverse','POST',{reason,effectiveOn:dateToday()});await load();}reasonDialog=null;}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}
 async function recordPayment(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';try{await call('/api/workspaces/'+workspace.selectedId+'/invoices/'+id+'/payments','POST',{amount,paidOn,accountId,categoryId,reference,idempotencyKey:crypto.randomUUID()});amount='';reference='';await load();}catch(e){error=e instanceof Error?e.message:t('error');}finally{busy=false;}}

</script>
<LoadingScope active={!!loading || !!busy} />
<svelte:head><title>CapyBudget · {invoice?.number??t('invoice')}</title></svelte:head>
{#if error}<ErrorState title={ux('errorTitle')} message={error} />{/if}{#if notice}<p role="status">{notice}</p>{/if}
{#if loading}<LoadingSkeleton rows={5} label={t('loading')} />{:else if invoice}<p class="back"><a href="/invoices">← {t('invoices')}</a></p>
<div class="invoice-heading"><PageHeader eyebrow={t('studioMode').toUpperCase()} title={invoice.number??t('draft')}>
  {#snippet metadata()}<InvoiceStatus status={invoice.status} locale={ui.locale} />{/snippet}
  {#snippet actions()}<div class="actions">{#if invoice.state==='draft'&&canEdit}<Button variant="outline" onclick={saveDraft} disabled={busy}>{t('saveDraft')}</Button>{#if canManage}<Button onclick={issueInvoice} disabled={busy}>{t('issueInvoice')}</Button>{/if}{:else if invoice.state==='issued'}<Button variant="outline" onclick={downloadPdf} disabled={busy}>{t('downloadPdf')}</Button>{#if canManage}<Button onclick={sendInvoice} disabled={busy}>{t('sendInvoice')}</Button>{#if invoice.status!=='paid'}<Button variant="outline" onclick={resendPaymentLink} disabled={busy||!invoice.paymentLinkAvailable} title={invoice.paymentLinkAvailable?(ui.locale==='id'?'Kirim ulang tautan QRIS yang sama ke email penerima.':'Email the same QRIS link to the recipient again.'):(ui.locale==='id'?'Buat pembayaran QRIS yang aktif terlebih dahulu.':'Create an active QRIS payment first.')}>{ui.locale==='id'?'Kirim ulang tautan pembayaran':'Resend payment link'}</Button>{/if}{/if}{#if canManage&&invoice.status!=='paid'}<Button variant="destructive" onclick={askVoid} disabled={busy}>{t('voidInvoice')}</Button>{/if}{/if}</div>{/snippet}
</PageHeader></div>
<div class="grid"><Card.Root><Card.Header><Card.Title>{t('customer')}</Card.Title><Card.Description>{invoice.currency} · {formatDate(invoice.issueDate)} → {formatDate(invoice.dueDate)}</Card.Description></Card.Header><Card.Content><Field.FieldGroup class="fields">
<Field.Field><Field.FieldLabel for="customer">{t('customer')}</Field.FieldLabel><Input id="customer" bind:value={invoice.recipientSnapshot.name} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-email">{t('email')}</Field.FieldLabel><Input id="customer-email" type="email" bind:value={invoice.recipientSnapshot.email} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-phone">{t('phone')}</Field.FieldLabel><Input id="customer-phone" bind:value={invoice.recipientSnapshot.phone} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-street">{t('street')}</Field.FieldLabel><Input id="customer-street" bind:value={invoice.recipientSnapshot.address.street} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-city">{t('city')}</Field.FieldLabel><Input id="customer-city" bind:value={invoice.recipientSnapshot.address.city} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-region">{t('region')}</Field.FieldLabel><Input id="customer-region" bind:value={invoice.recipientSnapshot.address.region} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-postal">{t('postalCode')}</Field.FieldLabel><Input id="customer-postal" bind:value={invoice.recipientSnapshot.address.postalCode} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="customer-country">{t('country')}</Field.FieldLabel><Input id="customer-country" bind:value={invoice.recipientSnapshot.address.country} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="issue-date">{t('issueDate')}</Field.FieldLabel><DatePicker id="issue-date" bind:value={invoice.issue_date} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
<Field.Field><Field.FieldLabel for="due-date">{t('dueDate')}</Field.FieldLabel><DatePicker id="due-date" bind:value={invoice.due_date} disabled={invoice.state!=='draft'||!canEdit} /></Field.Field>
</Field.FieldGroup><div class="summary"><span>{t('paid')}: <MoneyDisplay amount={invoice.paidAmount} currency={invoice.currency} type="income" /></span><strong>{t('outstanding')}: <MoneyDisplay amount={invoice.outstanding} currency={invoice.currency} type={invoice.status==='overdue'?'expense':null} /></strong></div></Card.Content></Card.Root>
{#if canManage&&invoice.state==='issued'}<Card.Root class="collection-card"><Card.Header><Card.Title>{ui.locale==='id'?'Perkiraan penerimaan':'Collection estimate'}</Card.Title><Card.Description>{ui.locale==='id'?'Asumsi ini hanya untuk prakiraan dan tidak mengubah jatuh tempo faktur.':'Forecasting assumption only; it does not change the invoice due date.'}</Card.Description></Card.Header><Card.Content><Field.FieldGroup class="fields"><Field.Field><Field.FieldLabel for="collection-date">{ui.locale==='id'?'Tanggal penerimaan yang diperkirakan':'Expected collection date'}</Field.FieldLabel><DatePicker id="collection-date" bind:value={forecastDate} /></Field.Field><Field.Field><Field.FieldLabel for="collection-account">{ui.locale==='id'?'Akun penerimaan':'Receiving account'}</Field.FieldLabel><ChoiceSelect id="collection-account" bind:value={forecastAccountId} items={[{value: '', label: String(ui.locale==='id'?'Belum ditentukan':'Unassigned')}, ...(accounts.filter((x:any)=>x.currency===invoice.currency&&['cash','bank','e_wallet','savings'].includes(x.kind))).flatMap((account) => [{value: account.id, label: String(account.name)}])]} /></Field.Field></Field.FieldGroup><Button class="save-collection" variant="outline" onclick={saveCollectionForecast} disabled={busy}>{ui.locale==='id'?'Simpan asumsi':'Save estimate'}</Button></Card.Content></Card.Root>{/if}
<Card.Root><Card.Header><Card.Title>{t('invoice')}</Card.Title></Card.Header><Card.Content>{#if invoice.state==='draft'&&canEdit}<InvoiceDirectoryPicker workspaceId={workspace.selectedId} currency={invoice.currency} kind="contacts" disabled={busy} onCopy={(item)=>{invoice.contact_id=item.id;invoice.recipientSnapshot={name:item.name,email:item.details.email??'',phone:item.details.phone??'',taxId:item.details.taxId??'',address:{street:'',city:'',region:'',postalCode:'',country:'',...item.details.address}};}}/><InvoiceDirectoryPicker workspaceId={workspace.selectedId} currency={invoice.currency} kind="catalog" disabled={busy||invoice.lines.length>=100} onCopy={copyItem}/><div class="lines">{#each invoice.lines as line,i (line.id??i)}<div class="line"><Field.Field><Field.FieldLabel for={'line-description-'+i}>{t('description')}</Field.FieldLabel><Input id={'line-description-'+i} bind:value={line.description} maxlength={500} /></Field.Field><Field.Field><Field.FieldLabel for={'line-quantity-'+i}>{t('quantity')}</Field.FieldLabel><Input id={'line-quantity-'+i} bind:value={line.quantity} inputmode="decimal" /></Field.Field><Field.Field><Field.FieldLabel for={'line-price-'+i}>{t('unitPrice')}</Field.FieldLabel><AmountInput currency={invoice.currency} id={'line-price-'+i}  type={privacy.hidden?'password':'text'} bind:value={line.unitPrice} inputmode="decimal" /></Field.Field><Field.Field><Field.FieldLabel for={'line-discount-'+i}>{t('discount')}</Field.FieldLabel><AmountInput currency={invoice.currency} id={'line-discount-'+i}  type={privacy.hidden?'password':'text'} bind:value={line.discountAmount} inputmode="decimal" /></Field.Field><Field.Field><Field.FieldLabel for={'line-tax-'+i}>{t('taxRate')}</Field.FieldLabel><InvoiceTaxPicker id={'line-tax-'+i} bind:rateId={line.taxRateId} bind:manualRate={line.taxRate} rates={taxRates} enabled={taxEnabled} date={invoice.issue_date} /></Field.Field>{#if invoice.lines.length>1}<Button type="button" variant="ghost" onclick={()=>removeLine(i)}>{t('removeLine')}</Button>{/if}</div>{/each}</div><Button type="button" variant="outline" onclick={addLine} disabled={invoice.lines.length>=100}>{t('addLine')}</Button>{:else}<div class="rows">{#each invoice.lines as line (line.id)}<article><div><strong>{line.description}</strong><p>{line.quantity} × <MoneyDisplay amount={line.unitPrice} currency={invoice.currency} /></p></div><MoneyDisplay amount={line.totalAmount} currency={invoice.currency} /></article>{/each}</div>{/if}<div class="totals"><p>{t('subtotal')} <MoneyDisplay amount={invoice.subtotal} currency={invoice.currency} /></p><p>{t('discount')} <MoneyDisplay amount={invoice.discountTotal} currency={invoice.currency} type="expense" /></p><p>{t('tax')} <MoneyDisplay amount={invoice.taxTotal} currency={invoice.currency} /></p><p class="total">{t('total')} <MoneyDisplay amount={invoice.total} currency={invoice.currency} size="lg" /></p></div>{#if invoice.state==='draft'&&canEdit}<Field.FieldGroup class="fields extra"><Field.Field><Field.FieldLabel for="invoice-notes">{t('notes')}</Field.FieldLabel><Input id="invoice-notes" bind:value={invoice.notes} maxlength={4000} /></Field.Field><Field.Field><Field.FieldLabel for="payment-instructions">{t('paymentInstructions')}</Field.FieldLabel><Input id="payment-instructions" bind:value={invoice.payment_instructions} maxlength={2000} /></Field.Field></Field.FieldGroup>{:else if invoice.notes}<p class="hint">{t('notes')}: {invoice.notes}</p>{/if}</Card.Content></Card.Root></div>
{#if invoice.state==='issued'&&invoice.currency==='IDR'}<InvoicePaymentsPanel workspaceId={workspace.selectedId} invoiceId={invoice.id} onChanged={()=>void load()}/>{/if}
{#if canManage&&invoice.state==='issued'&&invoice.outstanding!=='0'}<Card.Root class="payment-card"><Card.Header><Card.Title>{t('recordPayment')}</Card.Title><Card.Description>{t('paymentHint')}</Card.Description></Card.Header><Card.Content><form onsubmit={recordPayment}><Field.FieldGroup class="fields"><Field.Field><Field.FieldLabel for="payment-amount">{t('total')}</Field.FieldLabel><AmountInput currency={invoice.currency} id="payment-amount"  type={privacy.hidden?'password':'text'} bind:value={amount} inputmode="decimal" required /></Field.Field><Field.Field><Field.FieldLabel for="payment-date">{t('paymentDate')}</Field.FieldLabel><DatePicker id="payment-date" bind:value={paidOn} required /></Field.Field><Field.Field><Field.FieldLabel for="payment-account">{t('receivingAccount')}</Field.FieldLabel><ChoiceSelect id="payment-account" bind:value={accountId} required items={[...(accounts.filter((x:any)=>x.currency===invoice.currency)).flatMap((account) => [{value: account.id, label: String(account.name)}])]} /></Field.Field><Field.Field><Field.FieldLabel for="payment-category">{t('incomeCategory')}</Field.FieldLabel><ChoiceSelect id="payment-category" bind:value={categoryId} required items={[...(categories).flatMap((category) => [{value: category.id, label: String(category.name)}])]} /></Field.Field><Field.Field><Field.FieldLabel for="payment-reference">{t('reference')}</Field.FieldLabel><Input id="payment-reference" bind:value={reference} maxlength={300} /></Field.Field></Field.FieldGroup><Button type="submit" disabled={busy||!accountId||!categoryId}>{busy?'…':t('recordPayment')}</Button></form></Card.Content></Card.Root>{/if}
{#if invoice.payments.length}<Card.Root class="payment-card"><Card.Header><Card.Title>{t('paid')}</Card.Title></Card.Header><Card.Content><div class="rows">{#each invoice.payments as payment (payment.id)}<article><div><MoneyDisplay amount={payment.amount} currency={invoice.currency} type="income" /><p>{formatDate(payment.paidOn)} · {payment.reference??'—'}{payment.reversedAt?' · '+t('reversePayment'):''}</p></div>{#if canManage&&!payment.reversedAt&&invoice.state==='issued'}<Button size="sm" variant="outline" onclick={()=>askReverse(payment)}>{t('reversePayment')}</Button>{/if}</article>{/each}</div></Card.Content></Card.Root>{/if}
{#if invoice.state==='issued'&&canManage&&invoice.status!=='paid'}<p class="hint">{invoice.paymentLinkAvailable?(ui.locale==='id'?'Email faktur akan menyertakan tautan pembayaran QRIS ini.':'The invoice email will include your current QRIS payment link.'):(ui.locale==='id'?'Buat pembayaran QRIS di bawah sebelum mengirim faktur agar tautan pembayaran disertakan dalam email.':'Create a QRIS payment below before sending the invoice to include its payment link in the email.')}</p>{/if}
{#if invoice.deliveries.length}<Card.Root class="payment-card"><Card.Header><Card.Title>{t('sendInvoice')}</Card.Title><Card.Description>{t('deliveryHistory')}</Card.Description></Card.Header><Card.Content>{#each invoice.deliveries as delivery (delivery.id)}<p>{delivery.purpose==='payment_link'?(ui.locale==='id'?'Tautan pembayaran':'Payment link'):delivery.purpose==='reminder'?(ui.locale==='id'?'Pengingat':'Reminder'):t('invoice')} · {delivery.state}{delivery.errorCode?' · '+t('sendFailed'):''}{delivery.acceptedAt?' · '+formatDateTime(delivery.acceptedAt,ui.locale):''}</p>{/each}</Card.Content></Card.Root>{/if}
<Dialog.Root open={!!reasonDialog} onOpenChange={(v)=>{if(!v)reasonDialog=null;}}>
  <Dialog.Content>
    <Dialog.Header><Dialog.Title>{reasonDialog?.mode==='void'?t('voidTitle'):t('reverseTitle')}</Dialog.Title></Dialog.Header>
    <Field.Field><Field.FieldLabel for="correction-reason">{t('reason')}</Field.FieldLabel><Input id="correction-reason" bind:value={reasonText} maxlength={500} /></Field.Field>
    <Dialog.Footer><Button variant="outline" onclick={()=>reasonDialog=null}>{t('cancel')}</Button><Button variant="destructive" onclick={confirmReason} disabled={busy||!reasonText.trim()}>{reasonDialog?.mode==='void'?t('voidInvoice'):t('reversePayment')}</Button></Dialog.Footer>
  </Dialog.Content>
</Dialog.Root>
{/if}
<style>
.invoice-heading :global(.page-header){flex-wrap:wrap}
.invoice-heading :global(.titles){flex:1 1 240px}
.invoice-heading :global(.page-header>.actions){flex:0 1 auto;max-width:100%}
@media(max-width:600px){.invoice-heading :global(.titles){flex-basis:auto}}
.back{margin:0 0 4px}.back a{color:var(--brand-ink);font-weight:600;text-decoration:none}.actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.grid{display:grid;grid-template-columns:1fr 1fr;align-items:start;gap:16px}:global(.fields){display:grid;grid-template-columns:1fr 1fr;gap:12px}.summary,.totals{display:grid;gap:8px;margin-top:16px}.summary{border-top:1px solid var(--border);padding-top:12px}.summary strong{text-align:right}.totals{max-width:330px;margin-left:auto}.totals p{display:flex;justify-content:space-between;margin:0}.total{border-top:2px solid var(--border);padding-top:8px;font-size:18px}.rows{display:grid;gap:8px}.rows article{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:8px 0;border-bottom:1px solid var(--border)}.rows p,.hint{color:var(--muted-foreground);font-size:13px;margin:4px 0}:global(.payment-card){margin-top:16px}:global(.collection-card){margin-top:16px}:global(.save-collection){margin-top:12px}:global(.payment-card form){display:grid;gap:16px}.lines{display:grid;gap:12px;margin-bottom:12px}.line{display:grid;grid-template-columns:2fr repeat(4,minmax(70px,1fr)) auto;gap:8px;align-items:end;border-bottom:1px solid var(--border);padding-bottom:12px}:global(.extra){margin-top:16px}@media(max-width:780px){.actions{justify-content:flex-start}.grid{grid-template-columns:1fr}}@media(max-width:650px){.line{grid-template-columns:repeat(2,minmax(0,1fr))}:global(.line)>:first-child{grid-column:1/-1}:global(.fields){grid-template-columns:1fr}}@media(max-width:480px){.line{grid-template-columns:minmax(0,1fr)}}</style>
